// Evento SESSION_NEW (lead novo): dados em body.content. Tambem aceita o formato antigo.
const b = $input.first().json.body ?? $input.first().json;
const c = b.content ?? b;

const companyId = c.companyId ?? b.companyId ?? null;
const contactId = c.contactId ?? c.contactDetails?.id ?? c.contact?.id ?? null;
const contactName = c.contactDetails?.name ?? c.contact?.name ?? 'Sem nome';
const sessionId = c.id ?? c.sessionId ?? c.session?.id ?? null;
const platform = (c.channelDetails?.platform ?? c.channel?.platform ?? c.channelType ?? '').toString().toUpperCase();
const utm = c.utm ?? c.session?.utm ?? null;
const utmSource = (utm && utm.source) ? String(utm.source).toUpperCase() : null;
const headline = (utm && utm.headline) ? utm.headline : null;
const lastContactMessage = c.lastMessageText ?? c.lastContactMessage ?? c.lastMessagesAggregated?.text ?? '';

const origemRaw = (utmSource ?? platform ?? 'DESCONHECIDO');
let origem;
if (origemRaw.includes('INSTAGRAM')) origem = 'INSTAGRAM';
else if (origemRaw.includes('FACEBOOK')) origem = 'FACEBOOK';
else origem = 'ORGANICO';

const agora = new Date();
const dataEntrada = agora.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const horaEntrada = agora.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });

let descricao = `Entrada: ${dataEntrada} às ${horaEntrada}`;
if (headline) descricao += `\nCampanha: ${headline}`;

return [{ json: { companyId, contactId, contactName, sessionId, platform, utmSource, origem, headline, lastContactMessage, dataEntrada, horaEntrada, descricao } }];

// Junta a linha (config achatada da clínica) com os dados preparados.
// 'alwaysOutputData' no node Supabase garante 1 item mesmo sem match.
const prep = $('Preparar Dados').first().json;
const row = $input.first().json || {};

const ativoBool = (row.ativo === true || String(row.ativo).toLowerCase() === 'true');
if (!row.helena_company_id || !ativoBool) {
  return [{ json: { ...prep, found: false } }];
}

const mapaPorOrigem = {
  FACEBOOK:  { tag_nome: row.fb_tag_nome,  panel_tag_id: row.fb_panel_tag_id,  contact_tag_id: row.fb_contact_tag_id },
  INSTAGRAM: { tag_nome: row.ig_tag_nome,  panel_tag_id: row.ig_panel_tag_id,  contact_tag_id: row.ig_contact_tag_id },
  ORGANICO:  { tag_nome: row.org_tag_nome, panel_tag_id: row.org_panel_tag_id, contact_tag_id: row.org_contact_tag_id }
};
const temOrigem = !!(mapaPorOrigem[prep.origem] && mapaPorOrigem[prep.origem].panel_tag_id);
const mapa = (temOrigem ? mapaPorOrigem[prep.origem] : mapaPorOrigem['ORGANICO']) || {};

return [{ json: {
  ...prep,
  found: true,
  clinica_nome: row.nome,
  token: row.helena_token,
  panel_id: row.panel_id,
  step_id: row.step_id,
  origem_aplicada: temOrigem ? prep.origem : 'ORGANICO',
  tag_nome: mapa.tag_nome ?? null,
  panel_tag_id: mapa.panel_tag_id ?? null,
  contact_tag_id: mapa.contact_tag_id ?? null
} }];

const resp = $input.first().json;
const arr = Array.isArray(resp) ? resp : (resp.items ?? resp.data ?? resp.cards ?? []);
const hasCard = Array.isArray(arr) && arr.length > 0;
const cardId = hasCard ? (arr[0].id ?? arr[0].cardId ?? null) : null;
return [{ json: { hasCard, cardId } }];

